use hy_check::{check_file, Verdict};
use hy_syntax::parse_file;
fn check_single_a7(src: &str) {
    let checked = check_file(&parse_file("test.hy", src).expect("parse"));
    assert_eq!((checked.verdict, checked.diagnostics.len()), (Verdict::Reject, 1), "got {:?} for:\n{}", checked.diagnostics, src);
    assert_eq!((checked.diagnostics[0].code.as_str(), checked.diagnostics[0].tier0_rule.as_deref()), ("HYB-E3003", Some("A7")));
}
fn codes(src: &str) -> Vec<String> { check_file(&parse_file("test.hy", src).expect("parse")).diagnostics.into_iter().map(|d| d.code).collect() }
#[test]
fn reject_closure_local_handle_use_after_consume_a7_1412() {
    for src in [
        "import \"rust/flate2\"\nfn main() {\n    f := fn() {\n        enc := flate2.new_writer()\n        _ = enc.finish()?\n        _ = enc.write(\"after\")?\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn(c bool) {\n        enc := flate2.new_writer()\n        if c {\n            _ = enc.finish()?\n        } else {\n            enc = flate2.new_writer()\n        }\n        _ = enc.write(\"after-if-else-reinit\")?\n    }\n    f(true)\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn() {\n        enc := flate2.new_writer()\n        if true {\n            _ = enc.finish()?\n            enc := flate2.new_writer()\n            _ = enc.finish()?\n        }\n        _ = enc.write(\"after-shadow-pop\")?\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn() {\n        enc := flate2.new_writer()\n        for i in 0..3 {\n            _ = i\n            _ = enc.write(\"x\")?\n            _ = enc.finish()?\n        }\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    enc := flate2.new_writer()\n    _ = enc.finish()?\n    f := fn() {\n        enc := flate2.new_writer()\n        _ = enc.finish()?\n        _ = enc.write(\"after\")?\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    if true {\n        enc := flate2.new_writer()\n        _ = enc.finish()?\n        f := fn() {\n            _ = enc.write(\"x\")?\n        }\n        f()\n    }\n}",
        "import \"rust/flate2\"\nfn main() {\n    a := flate2.new_writer()\n    _ = a.finish()?\n    f := fn() {\n        b := flate2.new_writer()\n        _ = b.finish()?\n        _ = a.write(\"x\")?\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn(c bool) {\n        enc := flate2.new_writer()\n        for i in 0..3 {\n            _ = i\n            if c {\n                _ = enc.finish()?\n                break\n            }\n        }\n        _ = enc.write(\"after-break\")?\n    }\n    f(true)\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn(c bool) {\n        enc := flate2.new_writer()\n        for i in 0..3 {\n            _ = i\n            if c {\n                _ = enc.finish()?\n                continue\n            }\n        }\n    }\n    f(true)\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn() {\n        enc := flate2.new_writer()\n        _ = enc.finish()?\n        g := fn() {\n            _ = enc.write(\"nested\")?\n        }\n        g()\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn() {\n        enc := flate2.new_writer()\n        _ = enc.finish()?\n        g := fn() {\n            _ = enc.write(\"x\")?\n        }\n        g()\n        enc = flate2.new_writer()\n        _ = enc.write(\"y\")?\n        _ = enc.finish()?\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn() {\n        if true {\n            e := flate2.new_writer()\n            _ = e.finish()?\n            g := fn() {\n                _ = e.write(\"x\")?\n            }\n            g()\n        }\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    a := flate2.new_writer()\n    f := fn() {\n        _ = a.finish()?\n        _ = a.write(\"captured-consumed-in-closure\")?\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn() {\n        enc := flate2.new_writer()\n        if _, err := enc.finish(); err != nil {\n            return\n        }\n        _ = enc.write(\"after-if-header-consume\")?\n    }\n    f()\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn(c bool) {\n        enc := flate2.new_writer()\n        _ = enc.finish()?\n        if c {\n            enc = flate2.new_writer()\n        } else {\n        }\n        _ = enc.write(\"after-empty-else\")?\n    }\n    f(true)\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn(a bool, b bool) {\n        enc := flate2.new_writer()\n        if a {\n            _ = enc.write(\"a\")?\n        } else if b {\n            _ = enc.finish()?\n        } else {\n            _ = enc.write(\"c\")?\n        }\n        _ = enc.write(\"after-else-if-consume\")?\n    }\n    f(false, true)\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn(a bool, b bool) {\n        enc := flate2.new_writer()\n        _ = enc.finish()?\n        if a {\n            enc = flate2.new_writer()\n        } else if b {\n            enc = flate2.new_writer()\n        }\n        _ = enc.write(\"after-else-if-no-else\")?\n    }\n    f(false, false)\n}",
        "import \"rust/flate2\"\nfn main() {\n    f := fn(c bool, n int) {\n        enc := flate2.new_writer()\n        if c {\n            _ = enc.finish()?\n            for i in 0..n {\n                _ = i\n                return\n            }\n        }\n        _ = enc.write(\"after-zero-trip-loop\")?\n    }\n    f(true, 0)\n}",
    ] { check_single_a7(src); }
}
#[test]
fn accept_closure_local_handle_reinitialized_and_no_leak_to_outer_scope_1412() {
    let src = "import \"rust/flate2\"\nfn make_pair() (flate2.writer, bool) { return flate2.new_writer(), true }\nfn main() {\n    enc := flate2.new_writer()\n    f := fn(ch chan flate2.writer, c bool) {\n        for w in ch {\n            _ = w.write(\"chan-elem\")?\n            _ = w.finish()?\n        }\n        enc := flate2.new_writer()\n        if c {\n            _ = enc.finish()?\n            return\n        }\n        _ = enc.write(\"before\")?\n        if true {\n            enc := flate2.new_writer()\n            g_inner := fn() {\n                _ = enc.write(\"fresh\")?\n                _ = enc.finish()?\n                for j in 0..2 {\n                    _ = j\n                    e_brk := flate2.new_writer()\n                    if c {\n                        _ = e_brk.finish()?\n                        break\n                    }\n                    _ = e_brk.write(\"in-nested-closure-loop\")?\n                    _ = e_brk.finish()?\n                }\n            }\n            g_inner()\n        }\n        _ = enc.write(\"still live\")?\n        _ = enc.finish()?\n        for i in 0..2 {\n            if true {\n                enc := flate2.new_writer()\n                _ = enc.write(\"nested-block-shadow-in-loop\")?\n                _ = enc.finish()?\n            }\n            _ = i\n        }\n        var enc2 flate2.writer\n        var ok bool\n        enc2, ok = make_pair()\n        _ = ok\n        if c {\n            _ = enc2.finish()?\n        } else {\n            _ = enc2.write(\"in-else\")?\n            _ = enc2.finish()?\n        }\n        if c {\n            enc2 = flate2.new_writer()\n        } else if !c {\n            enc2 = flate2.new_writer()\n        } else {\n            enc2 = flate2.new_writer()\n        }\n        _ = enc2.write(\"after-else-if-reinit\")?\n        _ = enc2.finish()?\n        enc2 = flate2.new_writer()\n        select {\n        <-ch:\n            _ = enc2.finish()?\n        <-ch:\n            _ = enc2.write(\"in-select\")?\n            _ = enc2.finish()?\n        }\n        enc2 = flate2.new_writer()\n        for i in 0..2 {\n            _ = i\n            if c {\n                _ = enc2.finish()?\n                break\n            }\n            _ = enc2.write(\"in-loop-after-break-branch\")?\n        }\n        for i in 0..2 {\n            _ = i\n            w_iter := flate2.new_writer()\n            if c {\n                _ = w_iter.finish()?\n                continue\n            }\n            _ = w_iter.write(\"in-loop-after-continue-branch\")?\n            _ = w_iter.finish()?\n        }\n        w_sh := flate2.new_writer()\n        for i in 0..1 {\n            _ = i\n            w_sh := flate2.new_writer()\n            _ = w_sh.finish()?\n            break\n        }\n        _ = w_sh.write(\"outer w_sh is live\")?\n        _ = w_sh.finish()?\n        enc2 = flate2.new_writer()\n        _ = enc2.write(\"multi-assign\")?\n        _ = enc2.finish()?\n    }\n    _ = f\n    _ = enc.write(\"outer live\")?\n    _ = enc.finish()?\n}";
    let checked = check_file(&parse_file("test.hy", src).expect("parse"));
    assert_eq!(checked.verdict, Verdict::Accept, "got {:?}", checked.diagnostics);
}
#[test]
fn closure_local_borrow_view_and_loop_mutation_conflict_a2_1412() {
    assert_eq!(codes("import \"rust/serde_json\"\nfn main() {\n    f := fn() {\n        doc := serde_json.parse(\"null\")?\n        users := doc.array(\"users\")?\n        doc.set(\"k\", \"v\")\n        _ = users.int(0)\n    }\n    f()\n}"), vec!["HYB-E3101"]);
    assert_eq!(codes("import \"rust/serde_json\"\nfn main() {\n    f := fn() {\n        doc := serde_json.parse(\"null\")?\n        for u in doc.array(\"users\")? {\n            doc.set(\"k\", \"v\")\n            _ = u\n        }\n    }\n    f()\n}"), vec!["HYB-E3101"]);
    let src_accept = "import \"rust/serde_json\"\nfn main() {\n    f := fn() {\n        doc := serde_json.parse(\"null\")?\n        users := doc.array(\"users\")?\n        _ = users.int(0)\n        doc.set(\"k\", \"v\")\n        for u in doc.array(\"users\")? {\n            _ = u\n        }\n        doc.set(\"k2\", \"v2\")\n    }\n    f()\n}";
    let checked = check_file(&parse_file("test.hy", src_accept).expect("parse"));
    assert_eq!(checked.verdict, Verdict::Accept, "got {:?}", checked.diagnostics);
}
